import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine watermark high_ts (single row expected)
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = pd.NaT

    # Step 1: keep only events strictly newer than watermark
    if pd.notna(high_ts):
        filtered = cdc_events[cdc_events["event_ts"] > high_ts].copy()
    else:
        filtered = cdc_events.copy()

    # Step 2: per product_id, pick the latest event by (event_ts, event_seq)
    if not filtered.empty:
        filtered = filtered.sort_values(
            by=["event_ts", "event_seq"], ascending=[True, True]
        )
        latest_events = filtered.groupby("product_id", as_index=False).tail(1)
    else:
        latest_events = filtered

    # Build dict of current snapshot state keyed by product_id
    snapshot_dict = {}
    for row in target_snapshot.itertuples(index=False):
        snapshot_dict[row.product_id] = (row.name, row.price, row.last_event_ts)

    # Step 3 & 4: apply surviving latest events
    for row in latest_events.itertuples(index=False):
        pid = row.product_id
        if row.op == "D":
            snapshot_dict.pop(pid, None)
        else:
            snapshot_dict[pid] = (row.name, row.price, row.event_ts)

    # Reconstruct new_snapshot DataFrame
    if snapshot_dict:
        pids = sorted(snapshot_dict.keys())
        records = [
            {
                "product_id": pid,
                "name": snapshot_dict[pid][0],
                "price": snapshot_dict[pid][1],
                "last_event_ts": snapshot_dict[pid][2],
            }
            for pid in pids
        ]
        new_snapshot = pd.DataFrame.from_records(records)
    else:
        new_snapshot = pd.DataFrame(
            columns=["product_id", "name", "price", "last_event_ts"]
        )

    # Enforce dtypes
    new_snapshot["product_id"] = new_snapshot["product_id"].astype("int64")
    new_snapshot["name"] = new_snapshot["name"].astype(object)
    new_snapshot["price"] = new_snapshot["price"].astype("float64")
    new_snapshot["last_event_ts"] = pd.to_datetime(
        new_snapshot["last_event_ts"]
    ).astype("datetime64[us]")

    new_snapshot = new_snapshot.reset_index(drop=True)

    return {"new_snapshot": new_snapshot}
